style.css:
@-moz-document domain("youtube.com") {
/* =================================
   GLOW RIOT RAINBOW PARTY LIGHTS
================================= */

@keyframes glow-riot-rainbow {
  0% { color: #ff0000; text-shadow: 0 0 8px #ff0000; }
  12.5% { color: #ff8000; text-shadow: 0 0 8px #ff8000; }
  25% { color: #ffff00; text-shadow: 0 0 8px #ffff00; }
  37.5% { color: #39ff14; text-shadow: 0 0 8px #39ff14; }
  50% { color: #00ffcc; text-shadow: 0 0 8px #00ffcc; }
  62.5% { color: #008cff; text-shadow: 0 0 8px #008cff; }
  75% { color: #a020f0; text-shadow: 0 0 8px #a020f0; }
  87.5% { color: #ff1493; text-shadow: 0 0 8px #ff1493; }
  100% { color: #ff0000; text-shadow: 0 0 8px #ff0000; }
}

/* HOMEPAGE AND RECOMMENDED VIDEO TITLES */

ytd-rich-grid-media #video-title,
ytd-rich-item-renderer #video-title,
ytd-rich-grid-media a#video-title-link,
ytd-rich-item-renderer a#video-title-link {
  font-family: "Cosmic Sans", "Comic Sans MS", cursive !important;
  font-weight: 900 !important;
  -webkit-text-fill-color: currentColor !important;
  animation: glow-riot-rainbow 8s steps(8, end) infinite !important;
}

/* PLAYLIST AND QUEUE VIDEO TITLES */

ytd-playlist-panel-video-renderer #video-title,
ytd-compact-video-renderer #video-title,
ytd-video-renderer #video-title {
  font-family: "Cosmic Sans", "Comic Sans MS", cursive !important;
  font-weight: 900 !important;
  -webkit-text-fill-color: currentColor !important;
  animation: glow-riot-rainbow 8s steps(8, end) infinite !important;
}

/* CHANNEL NAMES */

ytd-channel-name #text,
#channel-name a,
#channel-name yt-formatted-string {
  animation: glow-riot-rainbow 8s steps(8, end) infinite !important;
  -webkit-text-fill-color: currentColor !important;
}

/* =================================
   PURPLE AND PINK VIDEO BADGES
================================= */

/* VIDEO DURATION BADGES */

ytd-thumbnail-overlay-time-status-renderer {
  background: #260039 !important;
  color: #ff80df !important;
  border: 1px solid #ff1493 !important;
  border-radius: 6px !important;
  box-shadow: 0 0 8px rgba(255, 20, 147, 0.6) !important;
}

/* MIX BADGES */

ytd-thumbnail-overlay-side-panel-renderer {
  background: #260039 !important;
  color: #ff80df !important;
  border: 1px solid #ff1493 !important;
  border-radius: 6px !important;
  box-shadow: 0 0 8px rgba(255, 20, 147, 0.6) !important;
}

/* =================================
   SCENE KID SIDEBAR DECORATIONS
================================= */

/* YOU HEADER */

ytd-guide-collapsible-section-entry-renderer #header yt-formatted-string {
  font-family: "Comic Sans MS", "Comic Neue", cursive !important;
  color: #ff99e6 !important;
  font-size: 1.6rem !important;
  text-shadow: 0 0 8px rgba(255, 102, 217, 0.8) !important;
}

ytd-guide-collapsible-section-entry-renderer #header yt-formatted-string::before {
  content: "? ";
  color: #cc80ff;
}

/* SIDEBAR LINKS */

ytd-guide-collapsible-section-entry-renderer ytd-guide-entry-renderer yt-formatted-string.title {
  font-family: "Comic Sans MS", "Comic Neue", cursive !important;
  color: #f5ccff !important;
  letter-spacing: 0.3px;
}

ytd-guide-collapsible-section-entry-renderer ytd-guide-entry-renderer yt-formatted-string.title::before {
  content: "✯ ";
  color: #ff66d9;
}

ytd-guide-collapsible-section-entry-renderer ytd-guide-entry-renderer yt-formatted-string.title::after {
  content: " ♡";
  color: #b366ff;
}

/* ALTERNATING SKULL DECORATIONS */

ytd-guide-collapsible-section-entry-renderer ytd-guide-entry-renderer:nth-child(even) yt-formatted-string.title::after {
  content: " ?";
  color: #ff80df;
}

/* NEON HOVER EFFECT */

ytd-guide-collapsible-section-entry-renderer ytd-guide-entry-renderer:hover {
  background: linear-gradient(
    90deg,
    rgba(255, 102, 217, 0.25),
    rgba(153, 51, 255, 0.25)
  ) !important;
  border-radius: 15px !important;
  box-shadow: 0 0 10px rgba(255, 102, 217, 0.4) !important;
  transform: translateX(4px);
  transition: all 0.2s ease-in-out;
}

/* SIDEBAR ICONS */

ytd-guide-collapsible-section-entry-renderer yt-icon {
  color: #ff80df !important;
  filter: drop-shadow(0 0 4px rgba(255, 102, 217, 0.7));
}
}
